    `! this directory resolves to ${shadow.cwdRoot}, whose .cotal/auth holds a DIFFERENT trust chain for space "${t.space}".\n` +
    `  attach used ${t.root}, the root this mesh resolved to. The other one is not being used, and is worth a look.`,
  );

let cwdRoot: string;
let here: SpaceAuth | undefined;
let there: SpaceAuth | undefined;
try {
  cwdRoot = findCotalRoot(cwd);
  if (resolve(cwdRoot) === resolve(resolvedRoot)) return undefined;
  here = loadSpaceAuth(authDir(cwdRoot), space);
  there = here ? loadSpaceAuth(authDir(resolvedRoot), space) : undefined;
} catch {
  return undefined;
}
if (!here) return undefined;

